using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace Synkoz {
public sealed class ConditionR9 {public bool Enabled=true;public int Channel=1,Number=-1,Value=0;public string Kind="Tous",Compare="Tous";public double HoldMs=300,AttackMs,ReleaseMs,Reduction=100;public List<int> Targets=new List<int>();public void Validate(){if(Channel<1||Channel>32||Number< -1||Number>127||Value<0||Value>16383||!new[]{"Tous","Note","CC"}.Contains(Kind)||!new[]{"Tous","=","<",">"}.Contains(Compare)||Targets==null||Targets.Any(c=>c<1||c>32)||new[]{HoldMs,AttackMs,ReleaseMs,Reduction}.Any(v=>double.IsNaN(v)||double.IsInfinity(v)||v<0)||HoldMs>60000||AttackMs>60000||ReleaseMs>60000||Reduction>100)throw new Exception("Condition MIDI invalide.");}public bool Test(double value){return Compare=="Tous"||Compare=="="&&value==Value||Compare=="<"&&value<Value||Compare==">"&&value>Value;}}
public sealed partial class Montage {public List<ConditionR9> ConditionsR9=new List<ConditionR9>();}
public static class MidiChannelR9 {public static int Number(int channel,int track){return track>=17?track:channel+1;}public static int Number(GraphEvent15 e){return Number(e.Channel,e.Track);} }
public sealed class ConditionRunR9 {
 sealed class Point {public double Time,From,To;}
 readonly ConditionR9 rule;readonly List<Point> points=new List<Point>();
 public ConditionRunR9(ConditionR9 r,Montage m){r.Validate();rule=r;var intervals=new List<Tuple<double,double>>();if(!r.Enabled)return;
 if(r.Kind!="CC")foreach(var n in m.Notes.Where(n=>MidiChannelR9.Number(n.Channel,n.Track940)==r.Channel&&(r.Number<0||n.Note==r.Number)&&r.Test(n.Velocity)))intervals.Add(Tuple.Create(n.Start,n.Start+n.Duration));
 if(r.Kind!="Note")foreach(var group in m.CC.Where(c=>MidiChannelR9.Number(c.Channel,c.Track940)==r.Channel&&(r.Number<0||c.Number==r.Number)).GroupBy(c=>c.Number)){var values=group.OrderBy(c=>c.Time).ToArray();for(int i=0;i<values.Length;i++){var c=values[i];if(c.Value<0||!r.Test(c.Value))continue;double end=r.Compare=="Tous"?c.Time+r.HoldMs/1000:i+1<values.Length?values[i+1].Time:m.Duration;if(c.StateOnlyR9&&r.Compare=="Tous")continue;intervals.Add(Tuple.Create(c.Time,end));}}
 if(r.Kind=="Tous"&&r.Number<0&&r.Compare=="Tous")foreach(var pg in m.Programs940.Where(p=>MidiChannelR9.Number(p.Channel,p.Track940)==r.Channel))intervals.Add(Tuple.Create(pg.Time,pg.Time+r.HoldMs/1000));var merged=new List<Tuple<double,double>>();foreach(var x in intervals.OrderBy(v=>v.Item1)){if(merged.Count>0&&x.Item1<=merged[merged.Count-1].Item2){var old=merged[merged.Count-1];merged[merged.Count-1]=Tuple.Create(old.Item1,Math.Max(old.Item2,x.Item2));}else merged.Add(x);}foreach(var x in merged){Add(x.Item1,1);Add(x.Item2,0);}}
 double At(Point p,double t){double duration=(p.To>p.From?rule.AttackMs:rule.ReleaseMs)/1000;return duration<=0?p.To:p.From+(p.To-p.From)*Math.Max(0,Math.Min(1,(t-p.Time)/duration));}
 void Add(double time,double to){double from=points.Count==0?0:At(points[points.Count-1],time);points.Add(new Point{Time=time,From=from,To=to});}
 public double Factor(double time,int channel){if(channel<1||channel==rule.Channel||(rule.Targets.Count>0&&!rule.Targets.Contains(channel)))return 1;int lo=0,hi=points.Count;while(lo<hi){int mid=(lo+hi)/2;if(points[mid].Time<=time)lo=mid+1;else hi=mid;}return lo==0?1:1-At(points[lo-1],time)*rule.Reduction/100;}
}
