 combo("Si · canal MIDI",Enumerable.Range(1,32).Select(i=>i.ToString()).ToArray(),r.Channel.ToString(),v=>r.Channel=int.Parse(v));int depth;if(!criteria.TryGetValue(r,out depth))depth=r.Compare!="Tous"?3:r.Number>=0?2:r.Kind!="Tous"?1:0;if(depth>=1)combo("Type",new[]{"Tous","Note","CC"},r.Kind,v=>{r.Kind=v;});if(depth>=2)combo("Numéro (note ou CC)",new[]{"Tous"}.Concat(Enumerable.Range(0,128).Select(i=>i.ToString())).ToArray(),r.Number<0?"Tous":r.Number.ToString(),v=>r.Number=v=="Tous"?-1:int.Parse(v));if(depth>=3)combo("Valeur CC / vélocité",new[]{"Tous","=","<",">"},r.Compare,v=>r.Compare=v);if(depth>=3)num("Valeur",r.Value,0,16383,v=>r.Value=(int)v);if(depth<3){var more=new ComboBox{Width=280,DropDownStyle=ComboBoxStyle.DropDownList};more.Items.AddRange(new object[]{"+ Ajouter un critère",new[]{"Type de message","Numéro de note / CC","Comparaison de valeur"}[depth]});more.SelectedIndex=0;more.SelectedIndexChanged+=delegate{if(more.SelectedIndex==1){criteria[r]=depth+1;show();}};panel.Controls.Add(more);}if(depth>0){var less=new Button{Text="Retirer le dernier critère",AutoSize=true};less.Click+=delegate{criteria[r]=depth-1;if(depth==3)r.Compare="Tous";if(depth==2)r.Number=-1;if(depth==1)r.Kind="Tous";show();};panel.Controls.Add(less);}num("Maintien CC sans seuil (ms)",r.HoldMs,1,60000,v=>r.HoldMs=v);num("Alors · réduction (%) — 100 = mute",r.Reduction,0,100,v=>r.Reduction=v);num("Attaque (ms)",r.AttackMs,0,60000,v=>r.AttackMs=v);num("Release (ms)",r.ReleaseMs,0,60000,v=>r.ReleaseMs=v);var targets=new CheckedListBox{Width=350,Height=95,CheckOnClick=true};for(int i=1;i<=32;i++)targets.Items.Add("Canal "+i,r.Targets.Contains(i));targets.ItemCheck+=delegate(object s,ItemCheckEventArgs a){int ch=a.Index+1;r.Targets.Remove(ch);if(a.NewValue==CheckState.Checked)r.Targets.Add(ch);};panel.Controls.Add(new Label{Text="Cibles : aucune cochée = tous les autres canaux",AutoSize=true});panel.Controls.Add(targets);};listBox.SelectedIndexChanged+=delegate{show();};var add=new Button{Text="+ Condition",AutoSize=true};add.Click+=delegate{rules.Add(new ConditionR9());refresh();listBox.SelectedIndex=rules.Count-1;};var del=new Button{Text="Retirer",AutoSize=true};del.Click+=delegate{if(listBox.SelectedIndex>=0){rules.RemoveAt(listBox.SelectedIndex);refresh();show();}};var ok=new Button{Text="Valider",DialogResult=DialogResult.OK,AutoSize=true};bar.Controls.AddRange(new Control[]{add,del,ok});refresh();if(f.ShowDialog(this)==DialogResult.OK){foreach(var r in rules)r.Validate();model.ConditionsR9=rules;model.Save();}}}
}
